// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 value, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(value > 0 && value <= address(this).balance / 2);
        uint256 balanceBefore = address(c).balance;
        uint256 actorBalanceBefore = c.getBalance(actor);
        vm.deal(actor, value);
        vm.prank(actor);
        c.addToBalance{value: value}();
        assertTrue(address(c).balance == balanceBefore + value && c.getBalance(actor) == actorBalanceBefore + value);
    }
}
